export class ImapFlow {
  constructor(options: Record<string, unknown>);
  connect(): Promise<void>;
  logout(): Promise<void>;
  list(): Promise<Array<{ path: string; specialUse?: string }>>;
  mailboxOpen(path: string, options?: Record<string, unknown>): Promise<unknown>;
  getMailboxLock(path: string): Promise<{ release(): void }>;
  search(query: Record<string, unknown>, options?: Record<string, unknown>): Promise<number[]>;
  fetch(range: unknown, query: Record<string, unknown>, options?: Record<string, unknown>): AsyncIterable<{
    uid?: number;
    source?: Buffer;
    flags?: Set<string>;
    internalDate?: Date;
  }>;
}
